package kindergarten

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

var plantsByCode = map[rune]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
}

// Garden holds the plants assigned to each child.
type Garden struct {
	plants map[string][]string
}

// NewGarden parses a two-row diagram and assigns cups to the children
// alphabetically. The diagram must start with a newline so that each row
// is flush left, as in a raw string literal.
func NewGarden(diagram string, children []string) (*Garden, error) {
	rows := strings.Split(diagram, "\n")
	if len(rows) != 3 || rows[0] != "" {
		return nil, errors.New("diagram must consist of two rows, each preceded by a newline")
	}
	row1, row2 := rows[1], rows[2]
	if len(row1) != len(row2) {
		return nil, errors.New("diagram rows must be the same length")
	}
	if len(row1)%2 != 0 {
		return nil, errors.New("diagram must contain an even number of cups")
	}
	for _, code := range row1 + row2 {
		if _, ok := plantsByCode[code]; !ok {
			return nil, fmt.Errorf("invalid cup code %q", code)
		}
	}

	// Sort a copy so the caller's slice is left untouched.
	names := make([]string, len(children))
	copy(names, children)
	sort.Strings(names)

	seen := make(map[string]bool, len(names))
	for _, name := range names {
		if seen[name] {
			return nil, fmt.Errorf("duplicate name %q", name)
		}
		seen[name] = true
	}

	cups := len(row1) / 2
	if len(names) > cups {
		return nil, errors.New("more children than cups in the diagram")
	}

	g := &Garden{plants: make(map[string][]string, len(names))}
	for i, name := range names {
		off := i * 2
		g.plants[name] = []string{
			plantsByCode[row1[off]],
			plantsByCode[row1[off+1]],
			plantsByCode[row2[off]],
			plantsByCode[row2[off+1]],
		}
	}
	return g, nil
}

// Plants returns the four plants assigned to the given child, in the
// order: first row left to right, then second row left to right.
// ok is false if the child is not in the garden.
func (g *Garden) Plants(child string) ([]string, bool) {
	plants, ok := g.plants[child]
	return plants, ok
}

